<?php
declare(strict_types=1);require_once __DIR__.'/functions.php';require_login();$user=current_user();$q=db()->prepare('SELECT * FROM students WHERE user_id = ? LIMIT 1');$q->execute([$user['id']]);$student=$q->fetch();$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($student){$next=($student['face_data_status']==='Registered')?'Pending':'Registered';$u=db()->prepare('UPDATE students SET face_data_status = ? WHERE id = ? AND user_id = ?');$u->execute([$next,$student['id'],$user['id']]);$student['face_data_status']=$next;$notice=$next==='Registered'?'Face profile marked as registered.':'Face profile registration reset to pending.';}else{$notice='No student profile is linked to this account. Ask an administrator to create one.';}}$att=db()->prepare('SELECT COUNT(*) total, SUM(status="Present") present FROM attendance_logs WHERE student_id = ?');$att->execute([$student['id']??0]);$summary=$att->fetch();page_start('Profile & set face','profile_set_face.php');
?><div class="page-heading"><div><p class="overline">ACCOUNT SETTINGS</p><h1>Profile & set face</h1><p class="heading-subtitle">Manage your personal details and face recognition profile.</p></div></div><?php if($notice):?><div class="alert alert-info border-0"><?=e($notice)?></div><?php endif?><div class="profile-layout"><section class="content-card profile-card"><div class="profile-cover"><div class="profile-photo"><?=e(strtoupper(substr($user['name'],0,1)))?></div><span class="profile-status"><?=status_badge($student['face_data_status']??'Pending')?></span></div><div class="profile-main"><p class="overline">STUDENT PROFILE</p><h2><?=e($user['name'])?></h2><p class="profile-email"><?=e($user['email'])?></p><div class="profile-divider"></div><div class="profile-detail"><span>Student ID</span><strong><?=e($student['student_id_no']??'Not assigned')?></strong></div><div class="profile-detail"><span>Course & year</span><strong><?=e($student['course_year']??'Not assigned')?></strong></div><div class="profile-detail"><span>Account role</span><strong><?=e(ucfirst($user['role']))?></strong></div><div class="profile-detail"><span>Member since</span><strong><?=e(date('F Y',strtotime($user['created_at']??'now')))?></strong></div></div></section><section class="content-card face-card"><div class="face-card-head"><div><p class="overline">BIOMETRIC PROFILE</p><h2>Face recognition</h2><p>Use your face to make attendance check-ins quick and secure.</p></div><div class="face-icon">◎</div></div><div class="face-preview"><div class="face-ring"><span>◉</span></div><div><strong><?=$student&&$student['face_data_status']==='Registered'?'Your face profile is ready':'Your face profile is not set up'?></strong><p><?=$student&&$student['face_data_status']==='Registered'?'You can check in using face recognition.':'Register your face profile to enable quick check-ins.'?></p></div></div><div class="face-note"><span>ⓘ</span><p>Your biometric data is used only to verify your attendance and is handled securely.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn <?=$student&&$student['face_data_status']==='Registered'?'btn-outline-secondary':'btn-primary'?> face-action" <?=$student?'':'disabled'?>><?=$student&&$student['face_data_status']==='Registered'?'Reset face registration':'Set up face recognition'?> <span>→</span></button></form><p class="demo-note">Registration status controls are shown here; connect a camera enrollment flow to capture biometric data.</p></section><section class="content-card profile-summary"><h2>Your attendance</h2><div class="summary-metric"><strong><?=number_format((int)($summary['total']??0))?></strong><span>Total records</span></div><div class="summary-metric"><strong><?=number_format((int)($summary['present']??0))?></strong><span>Present check-ins</span></div></section></div><?php page_end();
